#!/bin/bash
# Yosys synthesis of the cache controller. Software estimates only; no FPGA hardware or place-and-route involved.
# The flows are the scripts in synth/*.ys:
#   generic_hier / generic_flat : technology-independent gates (memories become flip-flops + muxes)
#   ice40_flat / ice40_hier     : Lattice iCE40 primitives (LUT4, DFF, SB_RAM40_4K); representative FPGA resource model
# Outputs: synth/*_stat.txt, *.log, ice40.json, SUMMARY.md (generated by scripts/synth_summary.py)
# Exit status is nonzero if Yosys fails (including its `check -assert`).
set -eu
cd "$(dirname "$0")/.."
OUT=synth; mkdir -p $OUT
for f in generic_hier:generic generic_flat:generic_flat ice40_flat:ice40 ice40_hier:ice40_hier; do
  echo "== ${f%%:*} =="
  yosys -l $OUT/${f##*:}.log -s synth/${f%%:*}.ys > /dev/null
done
python3 scripts/synth_summary.py
echo "Reports: $OUT/SUMMARY.md and $OUT/*_stat.txt"
